export { FormBuilder } from '@/components/formedible/builder/form-builder';
export { FieldConfigurator } from '@/components/formedible/builder/field-configurator';
export { FormPreview } from '@/components/formedible/builder/form-preview';
export { CodeGenerator } from '@/components/formedible/builder/code-generator';
export { FieldStore, FieldStoreContext, globalFieldStore, useFieldStore } from '@/components/formedible/builder/field-store';
export {
  builderTab,
  codeTab,
  createTabsWithDisabled,
  createTabsWithOrder,
  defaultTabs,
  getBuilderAndCodeTabs,
  getBuilderAndPreviewTabs,
  getBuilderOnlyTabs,
  previewTab,
} from '@/components/formedible/builder/default-tabs';
export { defaultFormMetadata, builderFieldTypes } from '@/lib/formedible/builder-types';
export { fieldConfigFormDefinitions, getFieldConfigFormDefinition } from '@/lib/formedible/builder-config-registry';
export { generateCodeFromParsedConfig, generateFormCode } from '@/lib/formedible/code-generation';
export type {
  BuilderFieldTypeDefinition,
  FormBuilderProps,
  FormField,
  FormMetadata,
  FormPage,
  FormSettings,
  FormTab,
  TabConfig,
  TabContentProps,
} from '@/lib/formedible/builder-types';
export type { BuilderConfigContext, BuilderFieldValidationConfig, FieldConfigFormDefinition } from '@/lib/formedible/builder-config-types';
export type { CodeGenerationOptions, GeneratedCodeResult } from '@/lib/formedible/code-generation';
export { cn } from '@/lib/utils';

'use client';

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';

import { Button } from '@/components/ui/button';
import { FieldStore, FieldStoreContext } from '@/components/formedible/builder/field-store';
import { defaultTabs } from '@/components/formedible/builder/default-tabs';
import { cn } from '@/lib/utils';
import { defaultFormMetadata } from '@/lib/formedible/builder-types';
import type { FormBuilderProps, FormMetadata, TabConfig } from '@/lib/formedible/builder-types';
import type { FormedibleFieldType } from '@/components/formedible/lib/types';

const emptyInitialFields: NonNullable<FormBuilderProps['initialFields']> = [];

function orderTabs(tabs: readonly TabConfig[]): readonly TabConfig[] {
  return [...tabs]
    .filter((tab) => tab.enabled !== false)
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0));
}

export function FormBuilder({
  tabs = defaultTabs,
  defaultTab = 'builder',
  initialMetadata,
  initialFields,
  fieldStore: fieldStoreProp,
  onChange,
  onTabChange,
  onSubmit,
  className,
}: FormBuilderProps) {
  const sortedTabs = useMemo(() => orderTabs(tabs), [tabs]);
  const initialTab = sortedTabs.some((tab) => tab.id === defaultTab) ? defaultTab : sortedTabs[0]?.id ?? 'builder';
  const [activeTab, setActiveTab] = useState(initialTab);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [metadata, setMetadata] = useState<FormMetadata>({
    ...defaultFormMetadata,
    ...initialMetadata,
    settings: {
      ...defaultFormMetadata.settings,
      ...initialMetadata?.settings,
    },
  });

  const fieldStoreRef = useRef<FieldStore | null>(null);

  if (fieldStoreRef.current === null) {
    fieldStoreRef.current = fieldStoreProp ?? new FieldStore();
  }

  const fieldStore = fieldStoreRef.current;
  const importedInitialFields = initialFields ?? emptyInitialFields;
  const subscribeToStore = useCallback((listener: () => void) => fieldStore.subscribe(listener), [fieldStore]);
  const getStoreSnapshot = useCallback(() => fieldStore.getAllFields(), [fieldStore]);
  const fields = useSyncExternalStore(
    subscribeToStore,
    getStoreSnapshot,
    () => importedInitialFields,
  );

  useEffect(() => {
    fieldStore.importFields(importedInitialFields);
  }, [fieldStore, importedInitialFields]);

  const onChangeRef = useRef(onChange);

  useEffect(() => {
    onChangeRef.current = onChange;
  });

  useEffect(() => {
    onChangeRef.current?.(metadata, fields);
  }, [fields, metadata]);

  function updateMetadata(metadataUpdate: Partial<FormMetadata>): void {
    setMetadata((currentMetadata) => ({
      ...currentMetadata,
      ...metadataUpdate,
      settings: {
        ...currentMetadata.settings,
        ...metadataUpdate.settings,
      },
    }));
  }

  function addField(type: FormedibleFieldType): void {
    const fieldId = fieldStore.addField(type, metadata.pages[0]?.page ?? 1);
    setSelectedFieldId(fieldId);
  }

  function deleteField(fieldId: string): void {
    fieldStore.deleteField(fieldId);
    setSelectedFieldId((currentFieldId) => (currentFieldId === fieldId ? null : currentFieldId));
  }

  function duplicateField(fieldId: string): void {
    const duplicatedFieldId = fieldStore.duplicateField(fieldId);

    if (duplicatedFieldId !== null) {
      setSelectedFieldId(duplicatedFieldId);
    }
  }

  const activeTabConfig = sortedTabs.find((tab) => tab.id === activeTab) ?? sortedTabs[0];
  const ActiveTabComponent = activeTabConfig?.component;

  return (
    <FieldStoreContext.Provider value={fieldStore}>
      <div className={cn('flex min-h-[720px] flex-col rounded-xl border bg-background text-foreground', className)} data-builder-part="form-builder">
        <div className="flex flex-wrap items-center gap-3 border-b p-4">
          <div className="mr-auto">
            <h1 className="text-xl font-semibold">{metadata.title}</h1>
            <p className="text-sm text-muted-foreground">{metadata.description}</p>
          </div>
          <Button type="button" variant="outline" onClick={() => onSubmit?.(metadata, fields)}>
            Save Form
          </Button>
        </div>

        <div className="flex flex-wrap gap-2 border-b p-3">
          {sortedTabs.map((tab) => {
            const Icon = tab.icon;

            return (
              <Button
                key={tab.id}
                type="button"
                variant={tab.id === activeTab ? 'default' : 'ghost'}
                onClick={() => {
                  setActiveTab(tab.id);
                  onTabChange?.(tab.id);
                }}
              >
                {Icon !== undefined ? <Icon className="mr-2 size-4" /> : null}
                {tab.label}
              </Button>
            );
          })}
        </div>

        <div className="flex-1 p-4">
          {ActiveTabComponent !== undefined ? (
            <ActiveTabComponent
              metadata={metadata}
              fields={fields}
              selectedFieldId={selectedFieldId}
              onMetadataChange={updateMetadata}
              onAddField={addField}
              onSelectField={setSelectedFieldId}
              onDeleteField={deleteField}
              onDuplicateField={duplicateField}
            />
          ) : null}
        </div>
      </div>
    </FieldStoreContext.Provider>
  );
}

'use client';

import { useSyncExternalStore } from 'react';

import { FieldConfigurationForm } from '@/components/formedible/builder/field-configuration-form';
import { useFieldStore } from '@/components/formedible/builder/field-store';
import { cn } from '@/lib/utils';
import type { FormMetadata } from '@/lib/formedible/builder-types';
import type { FormField } from '@/lib/formedible/builder-types';

export interface FieldConfiguratorProps {
  readonly fieldId: string;
  readonly initialField: FormField;
  readonly availablePages?: readonly number[];
  readonly metadata?: FormMetadata;
  readonly onFieldChange?: (field: FormField) => void;
  readonly className?: string;
}

export function FieldConfigurator({
  fieldId,
  initialField,
  availablePages = [1],
  metadata,
  onFieldChange,
  className,
}: FieldConfiguratorProps) {
  const fieldStore = useFieldStore();

  const field = useSyncExternalStore(
    (listener) => fieldStore.subscribeToFieldUpdates(fieldId, listener),
    () => fieldStore.getField(fieldId) ?? initialField,
    () => initialField,
  );

  function updateField(fieldUpdate: Partial<FormField>): void {
    let updatedField: FormField | undefined;

    try {
      updatedField = fieldStore.updateField(fieldId, fieldUpdate);
    } catch (error) {
      console.error('[Formedible builder] field update rejected:', error);
      return;
    }

    if (updatedField === undefined) {
      return;
    }

    onFieldChange?.(updatedField);
  }

  return (
    <div className={cn('space-y-4 rounded-lg border bg-card p-4 text-card-foreground', className)} data-builder-part="field-configurator">
      <FieldConfigurationForm key={field.id} field={field} availablePages={availablePages} metadata={metadata} onFieldUpdate={updateField} />
    </div>
  );
}

'use client';

import { useMemo } from 'react';

import { useFormedible } from '@/components/formedible/hooks/use-formedible';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/components/formedible/lib/types';
import type { FormField, FormMetadata } from '@/lib/formedible/builder-types';
import { getFieldConfigFormDefinition } from '@/lib/formedible/builder-config-registry';

export interface FieldConfigurationFormProps {
  readonly field: FormField;
  readonly availablePages: readonly number[];
  readonly metadata?: FormMetadata;
  readonly onFieldUpdate: (fieldUpdate: Partial<FormField>) => void;
}

export function FieldConfigurationForm({ field, availablePages, metadata, onFieldUpdate }: FieldConfigurationFormProps) {
  const definition = getFieldConfigFormDefinition(field.type);
  const context = useMemo(() => ({ availablePages, metadata }), [availablePages, metadata]);
  const config = useMemo<UseFormedibleOptions<FormedibleFormValues>>(() => {
    const defaultValues = definition.defaultValues(field, context);

    return {
      fields: definition.fields(context),
      formOptions: {
        defaultValues,
        onChange: ({ value }) => {
          onFieldUpdate(definition.toFieldUpdate(value, field));
        },
        onSubmit: async ({ value }) => {
          onFieldUpdate(definition.toFieldUpdate(value, field));
        },
      },
      showSubmitButton: false,
    };
  }, [context, definition, field, onFieldUpdate]);
  const { Form } = useFormedible(config);

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-lg font-semibold">{definition.title}</h2>
        <p className="text-sm text-muted-foreground">{definition.description}</p>
      </div>
      <div className="space-y-4">
        <Form />
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react';

import { useFormedible } from '@/components/formedible/hooks/use-formedible';
import { cn } from '@/lib/utils';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/components/formedible/lib/types';

export interface FormPreviewProps {
  readonly config: UseFormedibleOptions<FormedibleFormValues>;
  readonly onFormSubmit?: (values: FormedibleFormValues) => void;
  readonly className?: string;
}

export function FormPreview({ config, onFormSubmit, className }: FormPreviewProps) {
  const previewConfig = useMemo<UseFormedibleOptions<FormedibleFormValues>>(() => ({
    ...config,
    formOptions: {
      ...config.formOptions,
      defaultValues: config.formOptions?.defaultValues,
      onSubmit: async ({ value }) => {
        onFormSubmit?.(value);
      },
    },
  }), [config, onFormSubmit]);
  const { Form } = useFormedible(previewConfig);

  if ((config.fields ?? []).length === 0) {
    return (
      <div className={cn('rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground', className)} data-builder-part="form-preview-empty">
        Add fields to preview the form.
      </div>
    );
  }

  return (
    <div className={cn('rounded-lg border bg-background p-4', className)} data-builder-part="form-preview">
      <Form />
    </div>
  );
}

'use client';

import { useMemo } from 'react';

import { generateFormCode } from '@/lib/formedible/code-generation';
import { cn } from '@/lib/utils';
import type { FormField, FormMetadata } from '@/lib/formedible/builder-types';

export interface CodeGeneratorProps {
  readonly metadata: FormMetadata;
  readonly fields: readonly FormField[];
  readonly className?: string;
}

export function CodeGenerator({ metadata, fields, className }: CodeGeneratorProps) {
  const generatedCode = useMemo(() => {
    try {
      return generateFormCode({
        title: metadata.title,
        description: metadata.description,
        fields,
        pages: metadata.pages,
        tabs: metadata.tabs,
        settings: metadata.settings,
      }).fullCode;
    } catch (error) {
      console.error('Failed to generate form code:', error);
      return error instanceof Error ? `// ${error.message}` : '// Failed to generate form code';
    }
  }, [metadata, fields]);

  return (
    <div className={cn('space-y-3', className)} data-builder-part="code-generator">
      <div>
        <h2 className="text-lg font-semibold">Generated Code</h2>
        <p className="text-sm text-muted-foreground">Copy this shadcn-installed Formedible source into your app.</p>
      </div>
      <pre className="max-h-[520px] overflow-auto rounded-lg border bg-muted p-4 text-sm">
        <code>{generatedCode}</code>
      </pre>
    </div>
  );
}

import { createContext, useContext } from 'react';

import type { FormedibleFieldType } from '@/components/formedible/lib/types';
import { builderFieldTypes } from '@/lib/formedible/builder-types';
import type { FormField } from '@/lib/formedible/builder-types';

type StructureListener = () => void;
type FieldListener = (field: FormField) => void;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function deepEqual(left: unknown, right: unknown): boolean {
  if (left === right) {
    return true;
  }

  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((item, index) => deepEqual(item, right[index]));
  }

  if (isRecord(left) && isRecord(right)) {
    const leftKeys = Object.keys(left);
    const rightKeys = Object.keys(right);

    if (leftKeys.length !== rightKeys.length) {
      return false;
    }

    return leftKeys.every((key) => Object.prototype.hasOwnProperty.call(right, key) && deepEqual(left[key], right[key]));
  }

  return false;
}

export class FieldStore {
  private fields: Record<string, FormField> = {};
  private fieldOrder: string[] = [];
  private fieldSnapshot: readonly FormField[] = [];
  private structureListeners = new Set<StructureListener>();
  private fieldListeners = new Map<string, Set<FieldListener>>();
  private nextId = 1;

  addField(type: FormedibleFieldType, selectedPage = 1): string {
    const id = this.createNextFieldId();

    const label = builderFieldTypes.find((fieldType) => fieldType.value === type)?.label ?? type;
    const field: FormField = {
      id,
      name: this.createNextFieldName(),
      type,
      label: `${label} Field`,
      required: false,
      page: selectedPage,
      ...this.defaultConfigForType(type),
    };

    this.fields[id] = field;
    this.fieldOrder.push(id);
    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();

    return id;
  }

  updateField(fieldId: string, fieldUpdate: Partial<FormField>): FormField | undefined {
    const currentField = this.fields[fieldId];

    if (currentField === undefined) {
      return undefined;
    }

    this.assertNameAvailable(fieldId, fieldUpdate.name, currentField.name);

    const updatedField: FormField = { ...currentField, ...fieldUpdate, id: fieldId };
    this.fields[fieldId] = updatedField;
    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();
    this.notifyFieldListeners(fieldId, updatedField);

    return updatedField;
  }

  replaceField(fieldId: string, field: FormField): FormField {
    this.assertNameAvailable(fieldId, field.name, this.fields[fieldId]?.name);

    const updatedField = { ...field, id: fieldId };
    const isNewField = !this.fieldOrder.includes(fieldId);
    this.fields[fieldId] = updatedField;

    if (isNewField) {
      this.fieldOrder.push(fieldId);
    }

    this.advanceNextIdFromFieldId(fieldId);
    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();
    this.notifyFieldListeners(fieldId, updatedField);

    return updatedField;
  }

  deleteField(fieldId: string): void {
    if (this.fields[fieldId] === undefined) {
      return;
    }

    delete this.fields[fieldId];
    this.fieldOrder = this.fieldOrder.filter((id) => id !== fieldId);
    this.fieldListeners.delete(fieldId);
    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();
  }

  duplicateField(fieldId: string): string | null {
    const field = this.fields[fieldId];

    if (field === undefined) {
      return null;
    }

    const id = this.createNextFieldId();

    this.fields[id] = {
      ...field,
      id,
      name: this.createUniqueCopyName(field.name),
      label: `${String(field.label)} (Copy)`,
    };
    this.fieldOrder.push(id);
    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();

    return id;
  }

  getField(fieldId: string): FormField | undefined {
    return this.fields[fieldId];
  }

  getAllFields(): readonly FormField[] {
    return this.fieldSnapshot;
  }

  getFieldsByPage(page: number): readonly FormField[] {
    return this.getAllFields().filter((field) => (field.page ?? 1) === page);
  }

  getFieldsByTab(tabId: string): readonly FormField[] {
    return this.getAllFields().filter((field) => field.tab === tabId);
  }

  subscribe(listener: StructureListener): () => void {
    this.structureListeners.add(listener);

    return () => {
      this.structureListeners.delete(listener);
    };
  }

  subscribeToFieldUpdates(fieldId: string, listener: FieldListener): () => void {
    const fieldListenerSet = this.fieldListeners.get(fieldId) ?? new Set<FieldListener>();
    fieldListenerSet.add(listener);
    this.fieldListeners.set(fieldId, fieldListenerSet);

    return () => {
      fieldListenerSet.delete(listener);

      if (fieldListenerSet.size === 0) {
        this.fieldListeners.delete(fieldId);
      }
    };
  }

  importFields(fields: readonly FormField[]): void {
    if (deepEqual(fields, this.fieldSnapshot)) {
      return;
    }

    this.fields = {};
    this.fieldOrder = [];
    this.nextId = 1;

    for (const field of fields) {
      const id = field.id.length > 0 ? field.id : this.createNextFieldId();
      this.fields[id] = { ...field, id };
      this.fieldOrder.push(id);
      this.advanceNextIdFromFieldId(id);
    }

    this.rebuildFieldSnapshot();
    this.notifyStructureListeners();
  }

  clear(): void {
    this.fields = {};
    this.fieldOrder = [];
    this.fieldSnapshot = [];
    this.fieldListeners.clear();
    this.nextId = 1;
    this.notifyStructureListeners();
  }

  private createNextFieldId(): string {
    let id = `field_${this.nextId}`;

    while (this.fields[id] !== undefined) {
      this.nextId += 1;
      id = `field_${this.nextId}`;
    }

    this.nextId += 1;

    return id;
  }

  private assertNameAvailable(fieldId: string, requestedName: string | undefined, currentName: string | undefined): void {
    if (requestedName === undefined || requestedName === currentName) {
      return;
    }

    for (const [existingId, existingField] of Object.entries(this.fields)) {
      if (existingId !== fieldId && existingField.name === requestedName) {
        throw new Error(
          `Cannot use field name "${requestedName}" for field "${currentName ?? fieldId}" (${fieldId}): field "${existingField.name}" (${existingId}) already uses that name. Field names must be unique.`,
        );
      }
    }
  }

  private createNextFieldName(): string {
    const namesInUse = this.collectFieldNames();
    let counter = 1;

    while (namesInUse.has(`field_${counter}`)) {
      counter += 1;
    }

    return `field_${counter}`;
  }

  private createUniqueCopyName(baseName: string): string {
    const namesInUse = this.collectFieldNames();
    const baseCopyName = `${baseName}_copy`;

    if (!namesInUse.has(baseCopyName)) {
      return baseCopyName;
    }

    let counter = 2;

    while (namesInUse.has(`${baseCopyName}_${counter}`)) {
      counter += 1;
    }

    return `${baseCopyName}_${counter}`;
  }

  private collectFieldNames(): Set<string> {
    const names = new Set<string>();

    for (const fieldId of this.fieldOrder) {
      const field = this.fields[fieldId];

      if (field !== undefined) {
        names.add(field.name);
      }
    }

    return names;
  }

  private advanceNextIdFromFieldId(fieldId: string): void {
    const match = /^field_(\d+)$/.exec(fieldId);

    if (match === null) {
      return;
    }

    const numericId = Number.parseInt(match[1] ?? '', 10);

    if (Number.isSafeInteger(numericId) && numericId >= this.nextId) {
      this.nextId = numericId + 1;
    }
  }

  private rebuildFieldSnapshot(): void {
    this.fieldSnapshot = this.fieldOrder.map((id) => this.fields[id]).filter((field): field is FormField => field !== undefined);
  }

  private notifyStructureListeners(): void {
    for (const listener of this.structureListeners) {
      listener();
    }
  }

  private notifyFieldListeners(fieldId: string, field: FormField): void {
    const listeners = this.fieldListeners.get(fieldId);

    if (listeners === undefined) {
      return;
    }

    for (const listener of listeners) {
      listener(field);
    }
  }

  private defaultConfigForType(type: FormedibleFieldType): Partial<FormField> {
    if (type === 'select' || type === 'radio' || type === 'multiSelect' || type === 'combobox' || type === 'multiCombobox') {
      return {
        options: [
          { label: 'Option 1', value: 'option_1' },
          { label: 'Option 2', value: 'option_2' },
        ],
      };
    }

    if (type === 'autocomplete') {
      return {
        autocompleteConfig: {
          options: [
            { label: 'Suggestion 1', value: 'suggestion_1' },
            { label: 'Suggestion 2', value: 'suggestion_2' },
          ],
        },
      };
    }

    if (type === 'array') {
      return { arrayConfig: { itemType: 'string', itemLabel: 'Item', sortable: true } };
    }

    if (type === 'object') {
      return { objectConfig: { layout: 'stack', columns: 1, fields: [] } };
    }

    return {};
  }
}

export const globalFieldStore = new FieldStore();

export const FieldStoreContext = createContext<FieldStore | null>(null);

export function useFieldStore(): FieldStore {
  return useContext(FieldStoreContext) ?? globalFieldStore;
}

export type { FormField };

import { Code, Eye, Settings } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { CodeGenerator } from '@/components/formedible/builder/code-generator';
import { FieldConfigurator } from '@/components/formedible/builder/field-configurator';
import { FormPreview } from '@/components/formedible/builder/form-preview';
import { globalFieldStore } from '@/components/formedible/builder/field-store';
import { builderFieldTypes } from '@/lib/formedible/builder-types';
import type { TabConfig, TabContentProps } from '@/lib/formedible/builder-types';

function BuilderTabContent({ fields, selectedFieldId, metadata, onAddField, onSelectField, onDeleteField, onDuplicateField }: TabContentProps) {
  const selectedField = selectedFieldId === null ? undefined : fields.find((field) => field.id === selectedFieldId);
  const availablePages = metadata.pages.map((page) => page.page);

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]" data-builder-part="builder-tab">
      <div className="space-y-4">
        <div>
          <h2 className="text-lg font-semibold">Fields</h2>
          <p className="text-sm text-muted-foreground">Add, select, duplicate, and delete form fields.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          {builderFieldTypes.map((fieldType) => (
            <Button
              key={fieldType.value}
              type="button"
              variant="outline"
              size="sm"
              onClick={() => onAddField(fieldType.value)}
            >
              {fieldType.label}
            </Button>
          ))}
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          {fields.map((field) => (
            <div
              key={field.id}
              className="rounded-lg border bg-card p-3 text-card-foreground"
              data-selected={field.id === selectedFieldId ? 'true' : 'false'}
            >
              <button type="button" className="block w-full text-left" onClick={() => onSelectField(field.id)}>
                <span className="block font-medium">{field.label}</span>
                <span className="block text-xs text-muted-foreground">{field.name} · {field.type}</span>
              </button>
              <div className="mt-3 flex gap-2">
                <button type="button" className="text-xs text-muted-foreground hover:text-foreground" onClick={() => onDuplicateField(field.id)}>
                  Duplicate
                </button>
                <button type="button" className="text-xs text-destructive hover:underline" onClick={() => onDeleteField(field.id)}>
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
      {selectedField !== undefined ? (
        <FieldConfigurator fieldId={selectedField.id} initialField={selectedField} availablePages={availablePages} metadata={metadata} />
      ) : (
        <div className="rounded-lg border border-dashed p-6 text-sm text-muted-foreground">Select a field to configure it.</div>
      )}
    </div>
  );
}

function PreviewTabContent({ metadata, fields }: TabContentProps) {
  return (
    <FormPreview
      config={{
        fields,
        pages: metadata.layoutType === 'pages'
          ? metadata.pages.map((page) => ({ page: page.page, title: page.title, description: page.description }))
          : undefined,
        tabs: metadata.layoutType === 'tabs'
          ? metadata.tabs.map((tab) => ({ id: tab.id, label: tab.label, description: tab.description }))
          : undefined,
        submitLabel: metadata.settings.submitLabel,
        nextLabel: metadata.settings.nextLabel,
        previousLabel: metadata.settings.previousLabel,
        progress: metadata.settings.showProgress ? { showSteps: true, showPercentage: true } : undefined,
        formOptions: {
          defaultValues: Object.fromEntries(fields.map((field) => [field.name, previewDefaultValue(field)])),
        },
      }}
    />
  );
}

function previewDefaultValue(field: TabContentProps['fields'][number]): unknown {
  if (field.defaultValue !== undefined) {
    return field.defaultValue;
  }

  if (field.type === 'checkbox' || field.type === 'switch') {
    return false;
  }

  if (field.type === 'number' || field.type === 'slider' || field.type === 'rating') {
    return field.min ?? 0;
  }

  if (field.type === 'multiSelect' || field.type === 'multiCombobox' || field.type === 'array') {
    return [];
  }

  if (field.type === 'object') {
    return {};
  }

  if (field.type === 'file' || field.type === 'location') {
    return null;
  }

  return '';
}

function CodeTabContent({ metadata, fields }: TabContentProps) {
  return <CodeGenerator metadata={metadata} fields={fields} />;
}

