function numberLabelArray(value: unknown, valueKey: string): readonly { readonly value: number; readonly label: string }[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is Record<string, unknown> => typeof item === 'object' && item !== null)
    .map((item) => ({ value: typeof item[valueKey] === 'number' ? item[valueKey] : Number(item[valueKey]), label: typeof item.label === 'string' ? item.label : '' }))
    .filter((item) => Number.isFinite(item.value));
}

function sliderValueMapping(value: unknown): readonly { readonly sliderValue: number; readonly displayValue: string; readonly label?: string }[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is Record<string, unknown> => typeof item === 'object' && item !== null)
    .map((item) => ({
      sliderValue: typeof item.sliderValue === 'number' ? item.sliderValue : Number(item.sliderValue),
      displayValue: stringConfigValue(item.displayValue),
      label: typeof item.label === 'string' && item.label.length > 0 ? item.label : undefined,
    }))
    .filter((item) => Number.isFinite(item.sliderValue) && item.displayValue.length > 0);
}

function currentNestedField(
  item: Record<string, unknown>,
  index: number,
  currentFields: readonly FormedibleFieldConfig<FormedibleFormValues>[] | undefined,
): FormedibleFieldConfig<FormedibleFormValues> | undefined {
  const byIndex = currentFields?.[index];

  if (byIndex !== undefined && typeof item.name === 'string' && byIndex.name === item.name) {
    return byIndex;
  }

  if (typeof item.name === 'string') {
    return currentFields?.find((field) => field.name === item.name) ?? byIndex;
  }

  return byIndex;
}

function nestedFieldsValue(
  value: unknown,
  currentFields: readonly FormedibleFieldConfig<FormedibleFormValues>[] | undefined,
): readonly FormedibleFieldConfig<FormedibleFormValues>[] {
  if (!Array.isArray(value)) {
    return [];
  }

  // The nested editor only exposes name/type/label/placeholder per item, so every update
  // carries just those keys. Spread-merge each edited item against the currently stored
  // nested field to preserve options, required, disabled, description and nested
  // arrayConfig/objectConfig that unrelated keystrokes would otherwise strip.
  return value
    .filter((item): item is Record<string, unknown> => typeof item === 'object' && item !== null)
    .map((item, index) => {
      const { placeholder: _editedPlaceholder, ...preserved } = currentNestedField(item, index, currentFields) ?? {};
      const merged: FormedibleFieldConfig<FormedibleFormValues> = {
        ...preserved,
        name: typeof item.name === 'string' && item.name.length > 0 ? item.name : 'nested_field',
        type: typeof item.type === 'string' ? item.type as FormedibleFieldType : 'text',
        label: typeof item.label === 'string' && item.label.length > 0 ? item.label : 'Nested Field',
      };
      const placeholder = typeof item.placeholder === 'string' && item.placeholder.length > 0 ? item.placeholder : undefined;

      return placeholder === undefined ? merged : { ...merged, placeholder };
    });
}

import type { ReactNode } from 'react';

import type { FormedibleFieldOption, FormedibleFormValues } from '@/components/formedible/lib/types';
import type { FormField } from '@/lib/formedible/builder-types';
import type { BuilderFieldValidationConfig } from '@/lib/formedible/builder-config-types';

export interface BuilderOptionValue {
  readonly label: string;
  readonly value: string;
  readonly disabled?: boolean;
  readonly description?: string;
}

export interface BuilderFieldWithValidation extends FormField {
  readonly builderValidation?: BuilderFieldValidationConfig;
}

export function reactNodeToBuilderText(value: ReactNode | undefined): string {
  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  return '';
}

export function stringValue(values: FormedibleFormValues, key: string): string {
  const value = values[key];
  return typeof value === 'string' ? value : '';
}

export function optionalStringValue(values: FormedibleFormValues, key: string): string | undefined {
  const value = stringValue(values, key).trim();
  return value.length > 0 ? value : undefined;
}

export function booleanValue(values: FormedibleFormValues, key: string): boolean {
  return values[key] === true;
}

export function optionalNumberValue(values: FormedibleFormValues, key: string): number | undefined {
  const value = values[key];

  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === 'string' && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  return undefined;
}

export function stringArrayValue(values: FormedibleFormValues, key: string): readonly string[] {
  const value = values[key];

  if (!Array.isArray(value)) {
    return [];
  }

  return value.filter((item): item is string => typeof item === 'string' && item.length > 0);
}

export function optionsToBuilderOptions(options: FormField['options']): readonly BuilderOptionValue[] {
  if (!Array.isArray(options)) {
    return [];
  }

  return options.map((option) => {
    if (typeof option === 'string') {
      return { label: option, value: option };
    }

    return {
      label: reactNodeToBuilderText(option.label) || option.value,
      value: option.value,
      disabled: option.disabled,
      description: reactNodeToBuilderText(option.description),
    };
  });
}

export function builderOptionsToOptions(value: unknown): readonly FormedibleFieldOption[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .filter((item): item is Record<string, unknown> => typeof item === 'object' && item !== null)
    .map((item) => {
      const optionValue = typeof item.value === 'string' ? item.value.trim() : '';
      const optionLabel = typeof item.label === 'string' ? item.label.trim() : '';
      const description = typeof item.description === 'string' && item.description.trim().length > 0 ? item.description.trim() : undefined;

      return {
        value: optionValue || optionLabel,
        label: optionLabel || optionValue,
        disabled: item.disabled === true,
        description,
      };
    })
    .filter((option) => option.value.length > 0 || reactNodeToBuilderText(option.label).length > 0);
}

export function baseDefaultValues(field: FormField, page: number): FormedibleFormValues {
  const fieldWithValidation = field as BuilderFieldWithValidation;
  const section = typeof field.section === 'object' && field.section !== null ? field.section : undefined;

  return {
    label: reactNodeToBuilderText(field.label),
    name: field.name,
    description: reactNodeToBuilderText(field.description),
    placeholder: field.placeholder ?? '',
    required: field.required === true,
    disabled: field.disabled === true,
    page: String(field.page ?? page),
    tab: field.tab ?? '',
    sectionTitle: typeof field.section === 'string' ? field.section : reactNodeToBuilderText(section?.title),
    sectionDescription: reactNodeToBuilderText(section?.description),
    requiredMessage: fieldWithValidation.builderValidation?.requiredMessage ?? '',
    minLength: fieldWithValidation.builderValidation?.minLength,
    maxLength: fieldWithValidation.builderValidation?.maxLength,
    pattern: fieldWithValidation.builderValidation?.pattern ?? '',
    validationMin: fieldWithValidation.builderValidation?.min,
    validationMax: fieldWithValidation.builderValidation?.max,
    minItems: fieldWithValidation.builderValidation?.minItems,
    maxItems: fieldWithValidation.builderValidation?.maxItems,
  };
}

export function baseFieldUpdate(values: FormedibleFormValues): Partial<FormField> {
  const sectionTitle = optionalStringValue(values, 'sectionTitle');
  const sectionDescription = optionalStringValue(values, 'sectionDescription');
  const pageText = stringValue(values, 'page');
  const page = Number.parseInt(pageText, 10);
  const builderValidation = validationFromValues(values);
  const update: Partial<BuilderFieldWithValidation> = {
    label: stringValue(values, 'label'),
    name: stringValue(values, 'name'),
    description: optionalStringValue(values, 'description'),
    placeholder: optionalStringValue(values, 'placeholder'),
    required: booleanValue(values, 'required'),
    disabled: booleanValue(values, 'disabled'),
    page: Number.isSafeInteger(page) ? page : undefined,
    tab: optionalStringValue(values, 'tab'),
    section: sectionTitle === undefined ? undefined : sectionDescription === undefined ? sectionTitle : { title: sectionTitle, description: sectionDescription },
    builderValidation,
  };

  return update;
}

function validationFromValues(values: FormedibleFormValues): BuilderFieldValidationConfig | undefined {
  const validation: BuilderFieldValidationConfig = {
    requiredMessage: optionalStringValue(values, 'requiredMessage'),
    minLength: optionalNumberValue(values, 'minLength'),
    maxLength: optionalNumberValue(values, 'maxLength'),
    pattern: optionalStringValue(values, 'pattern'),
    min: optionalNumberValue(values, 'validationMin'),
    max: optionalNumberValue(values, 'validationMax'),
    minItems: optionalNumberValue(values, 'minItems'),
    maxItems: optionalNumberValue(values, 'maxItems'),
  };

  return Object.values(validation).some((value) => value !== undefined) ? validation : undefined;
}

import type { ReactNode } from 'react';

import type {
  FormedibleFieldConfig,
  FormedibleFormValues,
  UseFormedibleOptions,
} from '@/components/formedible/lib/types';
import type { BuilderFieldValidationConfig } from '@/lib/formedible/builder-config-types';
import type { FormPage, FormSettings, FormTab } from '@/lib/formedible/builder-types';

export interface CodeGenerationOptions {
  readonly title?: string;
  readonly description?: string;
  readonly fields: readonly FormedibleFieldConfig<FormedibleFormValues>[];
  readonly pages?: readonly FormPage[];
  readonly tabs?: readonly FormTab[];
  readonly settings?: Partial<FormSettings>;
}

export interface GeneratedCodeResult {
  readonly fullCode: string;
  readonly formConfig: string;
  readonly schemaCode: string;
}

interface SerializedPageConfig {
  readonly page: number;
  readonly title: string;
  readonly description?: string;
}

interface SerializedTabConfig {
  readonly id: string;
  readonly label: string;
  readonly description?: string;
}

function reactNodeToCode(value: ReactNode): string {
  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  return '';
}

function stringLiteral(value: string): string {
  return JSON.stringify(value);
}

function isValidRegexPattern(pattern: string): boolean {
  try {
    new RegExp(pattern);
    return true;
  } catch {
    return false;
  }
}

function arrayItemSchemaCode(itemType: NonNullable<FormedibleFieldConfig<FormedibleFormValues>['arrayConfig']>['itemType']): string {
  if (itemType === 'number') {
    return 'z.number()';
  }

  if (itemType === 'checkbox' || itemType === 'switch') {
    return 'z.boolean()';
  }

  if (itemType === 'object') {
    return 'z.record(z.string(), z.unknown())';
  }

  return 'z.string()';
}

function fieldSchemaCode(field: FormedibleFieldConfig<FormedibleFormValues>): string {
  const label = reactNodeToCode(field.label) || field.name;
  const builderValidation = getBuilderValidation(field);
  let schema = 'z.string()';

  if (field.type === 'email') {
    schema = 'z.string().email()';
  }

  if (field.type === 'url') {
    schema = 'z.string().url()';
  }

  if (field.type === 'number' || field.type === 'slider' || field.type === 'rating') {
    schema = 'z.number()';
  }

  if (field.type === 'checkbox' || field.type === 'switch') {
    schema = 'z.boolean()';
  }

  if (field.type === 'array') {
    schema = `z.array(${arrayItemSchemaCode(field.arrayConfig?.itemType)})`;
  }

  if (field.type === 'multiSelect' || field.type === 'multiselect') {
    schema = 'z.array(z.string())';
  }

  if (field.type === 'object') {
    schema = 'z.object({}).passthrough()';
  }

  if (builderValidation?.minLength !== undefined && schema.startsWith('z.string()')) {
    schema = `${schema}.min(${builderValidation.minLength})`;
  }

  if (builderValidation?.maxLength !== undefined && schema.startsWith('z.string()')) {
    schema = `${schema}.max(${builderValidation.maxLength})`;
  }

  if (builderValidation?.pattern !== undefined && schema.startsWith('z.string()') && isValidRegexPattern(builderValidation.pattern)) {
    schema = `${schema}.regex(new RegExp(${stringLiteral(builderValidation.pattern)}))`;
  }

  if (builderValidation?.min !== undefined && schema.startsWith('z.number()')) {
    schema = `${schema}.min(${builderValidation.min})`;
  }

  if (builderValidation?.max !== undefined && schema.startsWith('z.number()')) {
    schema = `${schema}.max(${builderValidation.max})`;
  }

  if (builderValidation?.minItems !== undefined && schema.startsWith('z.array(')) {
    schema = `${schema}.min(${builderValidation.minItems})`;
  }

  if (builderValidation?.maxItems !== undefined && schema.startsWith('z.array(')) {
    schema = `${schema}.max(${builderValidation.maxItems})`;
  }

  if (field.required === true && schema.startsWith('z.string()')) {
    return `${schema}.min(1, ${stringLiteral(builderValidation?.requiredMessage ?? `${label} is required`)})`;
  }

  if (field.required === true && schema === 'z.boolean()') {
    return `${schema}.refine((value) => value === true, { message: ${stringLiteral(builderValidation?.requiredMessage ?? `${label} is required`)} })`;
  }

  return field.required === true ? schema : `${schema}.optional()`;
}

function getBuilderValidation(field: FormedibleFieldConfig<FormedibleFormValues>): BuilderFieldValidationConfig | undefined {
  const validation = field.builderValidation;
  return typeof validation === 'object' && validation !== null && !Array.isArray(validation) ? validation as BuilderFieldValidationConfig : undefined;
}

function serializeField(field: FormedibleFieldConfig<FormedibleFormValues>): Record<string, unknown> {
  const serialized: Record<string, unknown> = {
    name: field.name,
    type: field.type ?? 'text',
    label: reactNodeToCode(field.label) || field.name,
  };

  const optionalKeys = [
    'description',
    'placeholder',
    'defaultValue',
    'required',
    'disabled',
    'page',
    'tab',
    'section',
    'help',
    'options',
    'datalist',
    'min',
    'max',
    'step',
    'rows',
    'maxLength',
    'mask',
    'textareaConfig',
    'passwordConfig',
    'numberConfig',
    'dateConfig',
    'sliderConfig',
    'ratingConfig',
    'multiSelectConfig',
    'comboboxConfig',
    'autocompleteConfig',
    'maskedInputConfig',
    'multiComboboxConfig',
    'colorConfig',
    'phoneConfig',
    'durationConfig',
    'locationConfig',
    'fileConfig',
    'arrayConfig',
    'objectConfig',
  ] as const;

  for (const key of optionalKeys) {
    const value = field[key];

    if (value !== undefined && typeof value !== 'function') {
      serialized[key] = key === 'description' ? reactNodeToCode(value as ReactNode) : value;
    }
  }

  return serialized;
}

function serializePages(pages: readonly FormPage[] | undefined): readonly SerializedPageConfig[] | undefined {
  if (pages === undefined || pages.length <= 1) {
    return undefined;
  }

  return pages.map((page) => ({
    page: page.page,
    title: page.title,
    description: page.description,
  }));
}

function serializeTabs(tabs: readonly FormTab[] | undefined): readonly SerializedTabConfig[] | undefined {
  if (tabs === undefined || tabs.length <= 1) {
    return undefined;
  }

  return tabs.map((tab) => ({
    id: tab.id,
    label: tab.label,
    description: tab.description,
  }));
}

const identifierKeyPattern = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const lineBreakPattern = /[\r\n\u2028\u2029]/;

function assertFieldNameSafeForCode(name: string): void {
  if (lineBreakPattern.test(name)) {
    throw new Error(`Field name must not contain line breaks because it is emitted into generated code: ${JSON.stringify(name)}`);
  }
}

function schemaPropertyKey(name: string): string {
  // Plain identifiers render bare for readable output. Every other name is emitted as a
  // computed `[JSON.stringify(name)]` key: JSON.stringify escapes quotes, backslashes and
  // control characters so crafted names stay a single inert string token (no schema source
  // injection), and the computed form keeps even `__proto__` from triggering object-literal
  // prototype-setter semantics. Both forms are valid TypeScript for any string.
  if (name !== '__proto__' && identifierKeyPattern.test(name)) {
    return name;
  }

  return `[${JSON.stringify(name)}]`;
}

export function generateFormCode(options: CodeGenerationOptions): GeneratedCodeResult {
  const schemaFields = options.fields
    .map((field) => {
      assertFieldNameSafeForCode(field.name);
      return `  ${schemaPropertyKey(field.name)}: ${fieldSchemaCode(field)}`;
    })
    .join(',\n');
  const schemaCode = `z.object({${schemaFields.length > 0 ? `\n${schemaFields}\n` : ''}})`;
  const configObject: Record<string, unknown> = {
    fields: options.fields.map(serializeField),
    formOptions: {
      defaultValues: {},
      onSubmit: 'FORMEDIBLE_SUBMIT_HANDLER',
    },
  };

  if (options.title !== undefined && options.title.length > 0) {
    configObject.title = options.title;
  }

  if (options.description !== undefined && options.description.length > 0) {
    configObject.description = options.description;
  }

  const pages = serializePages(options.pages);

  if (pages !== undefined) {
    configObject.pages = pages;
  }

  const tabs = serializeTabs(options.tabs);

  if (tabs !== undefined) {
    configObject.tabs = tabs;
  }

  if (options.settings?.submitLabel !== undefined) {
    configObject.submitLabel = options.settings.submitLabel;
  }

  if (options.settings?.nextLabel !== undefined) {
    configObject.nextLabel = options.settings.nextLabel;
  }

  if (options.settings?.previousLabel !== undefined) {
    configObject.previousLabel = options.settings.previousLabel;
  }

  if (options.settings?.showProgress === true) {
    configObject.progress = { showSteps: true, showPercentage: true };
  }

  const formConfig = JSON.stringify(configObject, null, 2)
    .replace('"FORMEDIBLE_SUBMIT_HANDLER"', 'async ({ value }) => {\n      window.dispatchEvent(new CustomEvent(\'formedible-submit\', { detail: value }));\n    }');
  const fullCode = `import { z } from 'zod';\n\nimport { useFormedible } from '@/components/formedible/hooks/use-formedible';\n\nexport function MyForm() {\n  const schema = ${schemaCode};\n  const { Form } = useFormedible({\n    ...${formConfig},\n    schema,\n  });\n\n  return <Form />;\n}\n`;

  return {
    fullCode,
    formConfig,
    schemaCode,
  };
}

export function generateCodeFromParsedConfig(config: UseFormedibleOptions<FormedibleFormValues>): GeneratedCodeResult {
  return generateFormCode({
    title: typeof config.title === 'string' ? config.title : undefined,
    description: typeof config.description === 'string' ? config.description : undefined,
    fields: config.fields ?? [],
    pages: config.pages?.map((page) => ({
      page: page.page,
      title: reactNodeToCode(page.title) || `Page ${page.page}`,
      description: reactNodeToCode(page.description),
    })),
    tabs: config.tabs?.flatMap((tab) => {
      if (typeof tab === 'string') {
        return [];
      }

      return [{
        id: tab.id,
        label: reactNodeToCode(tab.label) || tab.id,
        description: reactNodeToCode(tab.description),
      }];
    }),
    settings: {
      submitLabel: reactNodeToCode(config.submitLabel),
      nextLabel: reactNodeToCode(config.nextLabel),
      previousLabel: reactNodeToCode(config.previousLabel),
      showProgress: config.progress !== undefined,
    },
  });
}
